// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor) public {
        // The deployer (this test contract) is the owner; the caller must be admissible (not owner) for the rule to apply.
        vm.assume(actor != address(this));
        vm.prank(actor);
        bool ok;
        try c.sudicideAnyone() { ok = true; } catch { ok = false; }
        // Reference: non-owner calls always revert. Mutant lets non-owners through.
        assertTrue(ok == false, "non-owner must not be able to sudicideAnyone");
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function testNonOwnerCannotSelfDestruct(address caller) public {
        require(caller != address(0));
        bool reverted = false;
        bool succeeded;
        (succeeded) = true;
        try c.sudicideAnyone() { reverted = false; }
        catch { reverted = true; }
        assert(reverted);
    }
    receive() external payable {}
    fallback() external payable {}
}

